-- Optional schema reference. The one-time setup.php creates these tables automatically.
-- Import into a NEW online database only; do not import into your existing XAMPP database.
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE agents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(40) NULL, address VARCHAR(255) NULL, status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory_releases (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, agent_id INT UNSIGNED NOT NULL, package_kg DECIMAL(8,2) NOT NULL, quantity INT UNSIGNED NOT NULL, released_at DATE NOT NULL, notes VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_release_agent FOREIGN KEY (agent_id) REFERENCES agents(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE deliveries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, agent_id INT UNSIGNED NOT NULL, customer_name VARCHAR(120) NOT NULL, customer_phone VARCHAR(40) NULL, package_kg DECIMAL(8,2) NOT NULL, quantity INT UNSIGNED NOT NULL, price_per_kg DECIMAL(10,2) NOT NULL, delivery_date DATE NOT NULL, status ENUM('Delivered','Pending','Cancelled') NOT NULL DEFAULT 'Delivered', notes VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_delivery_agent FOREIGN KEY (agent_id) REFERENCES agents(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE remittances (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, agent_id INT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, remittance_date DATE NOT NULL, reference_no VARCHAR(100) NULL, notes VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_remittance_agent FOREIGN KEY (agent_id) REFERENCES agents(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
